// naming it fileName in the multipart form. The body is buffered so the
// request is replayable and can be retried on 429/5xx per the retry policy.
func (s *FilesService) Upload(ctx context.Context, fileName string, content io.Reader, opts ...FilesOption) (*File, error) {
