func TestFilesService_Upload_RetriesOnRateLimit(t *testing.T) {
	t.Parallel()

	content := []byte("pdf-bytes")
	var calls int
	var payloads [][]byte
	client := newTestClientWithConfig(t, pipedrive.Config{RetryPolicy: &pipedrive.RetryPolicy{
		MaxAttempts:     3,
		BaseDelay:       time.Millisecond,
		MaxDelay:        time.Millisecond,
		RetryAllMethods: true,
	}}, func(w http.ResponseWriter, r *http.Request) {
		calls++
		body, err := io.ReadAll(r.Body)
		if err != nil {
			t.Fatalf("read request body: %v", err)
		}
		payloads = append(payloads, body)
		if calls == 1 {
			w.Header().Set("Content-Type", "application/json")
			w.WriteHeader(http.StatusTooManyRequests)
			_, _ = w.Write([]byte(`{"success":false,"error":"rate limited"}`))
			return
		}
		w.Header().Set("Content-Type", "application/json")
		_, _ = w.Write([]byte(`{"success":true,"data":{"id":12,"name":"contract.pdf"}}`))
	})

	file, err := client.Files.Upload(context.Background(), "contract.pdf", bytes.NewReader(content))
	if err != nil {
		t.Fatalf("Upload error: %v", err)
	}
	if file.ID != 12 {
		t.Fatalf("unexpected file: %#v", file)
	}
	if calls != 2 {
		t.Fatalf("expected 2 attempts, got %d", calls)
	}
	if len(payloads) != 2 || !bytes.Equal(payloads[0], payloads[1]) {
		t.Fatalf("expected identical replayed bodies")
	}
	if len(payloads) > 0 && !bytes.Contains(payloads[0], content) {
		t.Fatalf("expected multipart payload to contain file content")
	}
}

